const s = wb.getWorksheet('Sheet3');
for (let r = 3; r <= 14; r++) s.getRange(`B${r}`).setValue(`=INDEX(month,MATCH(MID(A${r},6,2),codes2,0))`);
const out = [];
for (let r = 3; r <= 14; r++) {
  const a = s.getRange(`A${r}`).getValues()[0][0];
  const check = await wb.evaluate(`=LOOKUP(2,1/SEARCH("_"&codes2&"_",A${r}),month)`);
  out.push([r, a, s.getRange(`B${r}`).getFormulas ? s.getRange(`B${r}`).getFormulas()[0][0] : '', s.getRange(`B${r}`).getValues()[0][0], String(check)].join(' | '));
}
log(out.join('\n'));
